import type { SaintRec } from "./types";

export const M03: SaintRec[] = [
  { key: "03-01", name: "свт. Макария (Невского), митрополита Московского и Коломенского", kind: "saint", desc: "Свт. Макарий (Парвицкий-Невский, 1835–1926) – выдающийся миссионер, «Апостол Алтая». Окончив семинарию, он добровольно отправился в Алтайскую миссию, где принял монашество и посвятил 36 лет проповеди среди местных народов, изучив их язык и переведя богослужебные книги." },
  { key: "03-01", name: "Собор святых Новосибирской митрополии", kind: "feast", desc: "По благословению Святейшего Патриарха Московского и всея Руси Кирилла утвержден день празднования Собора святых Новосибирской митрополии – 29 февраля (в день памяти святителя Макария (Невского), митрополита Московского)." },
  { key: "03-01", name: "Мчч. Персидских в Мартирополе", year: "IV", kind: "saint", desc: "Преподобный Маруф был епископом основанного им города Тигрита (по-гречески – Мартирополь), – пограничного города Византийской империи и Персии. Он прославился своей ученостью и благочестием, писал о мучениках, пострадавших за веру Христову " },
  { key: "03-01", name: "прп. Маруфа, епископа Месопотамского", kind: "saint", desc: "Преподобный Маруф был епископом основанного им города Тигрита (по-гречески – Мартирополь), – пограничного города Византийской империи и Персии. Он прославился своей ученостью и благочестием, писал о мучениках, пострадавших за веру Христову " },
  { key: "03-01", name: "Сщмч. Петра Успенского, пресвитера", kind: "saint", desc: "Священномученик Петр родился в 1876 году в селе Алексеевском Коломенского уезда Московской губернии [1] в семье священнослужителя Василия Успенского. По окончании Духовной семинарии Петр в 1901 году был рукоположен во диакона и в 1905 году " },
  { key: "03-01", name: "Кипрская", year: "Стромынская", kind: "saint", desc: "Одним из списков древней чудотворной Кипрской иконы Божией Матери является святыня не сохранившегося до наших дней Стромынского монастыря (бывшего Богородского уезда, Московской епархии), находящаяся ныне в Успенской церкви села Стромынь." },
  { key: "03-02", name: "Вмч. Феодора Тирона", kind: "saint", desc: "Святой мученик Феодор Тирон родился в Евхаитах (ныне деревня Бейузю, Турция), был воином мармаритского полка в городе Амасии Понтийской области (северо-восточная область Малой Азии, тянувшаяся вдоль берега Понта Эвксинского, т." },
  { key: "03-02", name: "сщмч. Ермогена, патриарха Московского и всея Руси, чудотворца", kind: "saint", desc: "Сщмч. Ермоген (ок. 1530–1612), патриарх Московский и всея Руси, был выдающимся церковным и государственным деятелем Смутного времени. Начав служение священником в Казани, он стал свидетелем обретения Казанской иконы Божией Матери и составил службу в её честь." },
  { key: "03-02", name: "Прп. Феодора молчаливого, Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Феодор Молчаливый, Печерский, избрал подвиг молчания, чтобы постоянно пребывать в богомыслии и удержать себя от прегрешений даже в слове. Прославился от Господа даром чудотворений." },
  { key: "03-02", name: "прав. Мариамны (Марии), сестры апостола от 12-ти Филиппа", kind: "saint", desc: "Праведная Мариамна, сестра святого апостола от 12-ти Филиппа (память 14 ноября), дала обет девства и стала спутницей своего брата и святого апостола Варфоломея (память 11 июня), деятельно помогая им в их апостольских трудах." },
  { key: "03-02", name: "мч. Мины Калликелада", kind: "saint", desc: "Святые мученики Мина, Ермоген и Евграф пострадали за веру во Христа при императоре Максимине (305–313). Святой Мина был послан императором из Афин в Александрию для подавления смут, возникших между христианами и язычниками." },
  { key: "03-02", name: "Михаила Никологорского", kind: "saint", desc: "Священномученик Михаил родился в 1883 году в селе Гребнево Щелковской волости Богородского уезда Московской губернии в семье псаломщика Михаила Никологорского, служившего в Никольской церкви в Гребневе." },
  { key: "03-02", name: "Павла Косминкова", kind: "saint", desc: "Протоиерей Павел родился в 1875 году в селе Новинки Серпуховского уезда в семье священника Василия Косминкова. По окончании Московской семинарии был рукоположен во священника, и с 1900 года служил в Покровской церкви в селе Лысцево Коломенского уезда." },
  { key: "03-02", name: "мц. Анны Четвериковой", kind: "saint", desc: "Анна Четверикова родилась в 1873 году. Мученическую кончину она приняла 2 марта 1940 года, когда ей было 67 лет. 6 октября 2006 года определением Священного Синода Русской Православной Церкви она была причислена к лику святых мучениц." },
  { key: "03-03", name: "Свт. Льва I, папы Римского", kind: "saint", desc: "Святитель Лев 1 Великий, папа Римский (440–461), получил прекрасное и разностороннее образование, которое открывало перед ним блестящую светскую карьеру." },
  { key: "03-03", name: "Прп. Космы Яхромского", kind: "saint", desc: "Преподобный Косма Яхромский был слугой одного боярина и во время продолжительной болезни своего господина утешал его чтением книг. Как-то, переезжая из города в город, они остановились на реке Яхроме." },
  { key: "03-03", name: "свт. Агапита исп., епископа Синадского (Фригийского)", kind: "saint", desc: "Святитель Агапит исповедник, епископ Синадский, родился в Каппадокии в правление императоров Диоклитиана (284–305) и Максимиана (284–305). Родители его были христиане." },
  { key: "03-03", name: "свт. Флавиана исп., патриарха Цареградского", kind: "saint", desc: "Святитель Флавиан исповедник, патриарх Цареградский, занимал кафедру при святом Константинопольском царе Феодосии Младшем (408–450) и его сестре благоверной царице Пульхерии (&dagger; 453; память 10 сентября)." },
  { key: "03-03", name: "Прп. Владимира (Терентьева), исп., игумена", kind: "saint", desc: "Преподобноисповедник Владимир родился в 1872 году в деревне Шибаново Псковского уезда Псковской губернии в семье крестьянина Терентия Терентьева и в крещении наречен был Василием." },
  { key: "03-04", name: "прп. Феодора Санаксарского", kind: "saint", desc: "Преподобный Феодор Санаксарский (в миру дворянин Иван Игнатьевич Ушаков) родился в 1718 году в сельце Бурнаково Романовского уезда Ярославской провинции." },
  { key: "03-04", name: "прп. Досифея Палестинского (VII), ученика прп. аввы Дорофея", kind: "saint", desc: "Преподобный Досифей, ученик преподобного аввы Дорофея (память 5 июня), жил в конце VI – начале VII вв., воспитывался в богатой и знатной семье. От слуг своего дяди, который был военачальником, юноша Досифей услышал рассказы о святом городе Иерусалиме, и ему захотелось побывать там." },
  { key: "03-04", name: "прп. Равулы Самосатского", kind: "saint", desc: "Преподобный Равула родился в сирийском городе Самосаты и получил хорошее образование. Будучи молодым, он принял иночество и подвизался в пустынях и горах, подражая святому пророку Илии (память 20 июля) и Крестителю Господню Иоанну (память 7 января, 24 февраля, 25 мая, 24 июня, 29 августа, 23 сентября, 12 октября)." },
  { key: "03-04", name: "Мч. Димитрия Волкова", kind: "saint", desc: "В 1939 году в городе Орехово-Зуево Московской области был закрыт последний из служивших еще тогда в районе храмов — Рождества Богородицы, строительство и благоукрашение которого продолжалось около тридцати лет — с 1872-го по 1901 год." },
  { key: "03-05", name: "Прп. Льва, епископа Катанского", kind: "saint", desc: "Святой Лев был епископом в городе Катане, в Сицилии. Он славился добротой и милосердием, христианской любовью к нищим и странникам. Господь удостоил его дара врачевания от различных болезней и чудотворений." },
  { key: "03-05", name: "Блгв. кн. Ярослава Мудрого", kind: "saint", desc: "Ярослав I, в Крещении Георгий (Юрий), Владимирович, Мудрый (ок. 978–989 – 1054), благоверный великий князь Киевский. Память 4 марта (20 февраля) в день кончины." },
  { key: "03-05", name: "прп. Агафона Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Агафон Печерский подвизался в Киево-Печерском монастыре в XIII–XIV вв. Он был великим постником, исцелял больных возложением на них руки, имел дар пророчества и предсказал время своей смерти." },
  { key: "03-05", name: "прмч. Корнилия Псково-Печерского, игумена", kind: "saint", desc: "Преподобномученик Корнилий Псково-Печерский (1501–1570) родился в Пскове в боярской семье. Родители его, Стефан и Мария, воспитывали сына в благочестии и страхе Божием." },
  { key: "03-05", name: "сщмч. Садока, епископа Персидского, и с ним 128-ми мучеников", kind: "saint", desc: "Сщмч. Садок, епископ Персидский, жил в первой половине IV века. За проповедь христианства он был арестован по приказу царя Сапора II вместе с 128 верующими." },
  { key: "03-05", name: "прп. Агафона, папы Римского", kind: "saint", desc: "Преподобный Агафон, папа Римский, происходил из богатой семьи, от благочестивых родителей христиан, давших ему хорошее образование. После их смерти святой Агафон раздал имение нищим и принял иночество." },
  { key: "03-05", name: "Сщмч. Николая Розова, пресвитера", kind: "saint", desc: "Священномученик Николай родился 27 ноября 1877 года в селе Жданово Курмышского уезда Симбирской губернии [1] в семье священника Василия Розова. Все три сына отца Василия стали священнослужителями, двое из них были диаконами — известный патр" },
  { key: "03-06", name: "Прп. Тимофея в Символех", kind: "saint", desc: "Преподобный Тимофей пустынник, родом итальянец, с юных лет подвизался в монастыре, называемом &quot;Символы&quot;, в Малой Азии, при горе Олимп. Архимандритом обители был преподобный Феоктист." },
  { key: "03-06", name: "свт. Евстафия, архиепископа Антиохийского", kind: "saint", desc: "Святитель Евстафий, архиепископ Антиохийский (323–331) родился в Сиде Памфилийском во второй половине III века. Он был епископом города Берии, пользовался любовью и уважением народа и по ходатайству паствы был возведен отцами I Вселенского Собора (325) на Антиохийскую кафедру." },
  { key: "03-06", name: "Свт. Георгия, епископа Амастридского", kind: "saint", desc: "Святитель Георгий, епископ Амастридский, происходил из города Кромны, близ города Амастриды при Черном море. Благочестивые и знатные родители его, Феодор и Мигефуса, дали ему хорошее образование, духовное и светское.", lifeId: "georgiy" },
  { key: "03-06", name: "Александра Вислянского", kind: "saint", desc: "Священномученик Александр родился в 1870 году в селе Архангельское Землянского уезда Воронежской губернии в семье псаломщика Иакова Вислянского. Окончив в 1893 году Воронежскую Духовную семинарию, Александр Яковлевич был до 1894 года учител" },
  { key: "03-06", name: "Даниила Алферова", kind: "saint", desc: "Священномученик Александр родился в 1870 году в селе Архангельское Землянского уезда Воронежской губернии в семье псаломщика Иакова Вислянского. Окончив в 1893 году Воронежскую Духовную семинарию, Александр Яковлевич был до 1894 года учител" },
  { key: "03-06", name: "Григория Хлебунова", kind: "saint", desc: "Священномученик Григорий родился в 1873 году в селе Шуватово Симбирской губернии в семье крестьян Никиты и Татьяны Хлебуновых. Первоначальное образование он получил в сельской школе, а остальное дополнилось самообразованием и церковным воспитанием, полученным в семье." },
  { key: "03-06", name: "Константина Пятикрестовского, пресвитера", kind: "saint", desc: "Священномученик Константин родился 31 мая 1877 года в Москве в семье диакона Михаила Пятикрестовского. Первоначальное образование Константин получил в духовном училище." },
  { key: "03-06", name: "Павла Широкогорова, диакона", kind: "saint", desc: "Священномученик Павел родился в 1878 году в Москве в семье диакона Павла Широкогорова. В 1900 году он окончил Московскую Духовную семинарию и служил учителем в Москве." },
  { key: "03-06", name: "мц. Ольги Кошелевой", kind: "saint", desc: "Мученица Ольга (Ольга Семеновна Кошелева) родилась 2 июля 1874 года в селе Нижний Белоомут Зарайского уезда Рязанской губернии в крестьянской семье; она была замужем за рабочим кожевенной фабрики Андреем Кошелевым и жила вместе с мужем и де" },
  { key: "03-06", name: "Козельщанская", year: "1881", kind: "saint", desc: "Козельщанская икона Божией Матери принадлежит к числу икон позднейших по времени прославления (1881) и вместе с тем к числу наиболее почитаемых. Икона эта итальянского происхождения и была привезена в Россию одной из придворных императрицы Елизаветы Петровны (1741–1761)." },
  { key: "03-07", name: "Обр е тение мощей мучеников, иже во Евгении", year: "395–423", kind: "saint", desc: "Во время гонений на христиан останки святых мучеников обычно погребались верующими в потаенных местах. Таким образом, в Царьграде близ ворот и башни, называемых Евгениевыми, оказались погребенными множество тел мучеников, имена которых оставались неизвестными Церкви." },
  { key: "03-07", name: "прп. Афанасия Павлопетрийского исп.", kind: "saint", desc: "Преподобный Афанасий родился в г. Константинополе от благочестивых родителей. Достигнув совершенного возраста, святой удалился в одну из Никомидийских обителей и там принял иноческий постриг." },
  { key: "03-07", name: "сщмчч. Михаила Горбунова", kind: "saint", desc: "Священномученик Михаил родился 2 сентября 1878 года в деревне Селиверстово Пошехонского уезда Ярославской губернии в семье крестьянина Петра Горбунова." },
  { key: "03-07", name: "Иоанна Орлова", kind: "saint", desc: "Священномученик Иоанн родился 1 ноября 1881 года в деревне Любучаны Подольского уезда Московской губернии в семье священника Иоанна Петровича Орлова, служившего в кладбищенской Воскресенской церкви в Подольске." },
  { key: "03-07", name: "Виктора Моригеровского", kind: "saint", desc: "Священномученик Виктор родился 17 апреля 1872 года в селе Минеево Дмитровского уезда Московской губернии в семье священника Иоанна Моригеровского. Виктор Иванович окончил в 1889 году Заиконоспасское духовное училище, в 1896 году — Вифанскую" },
  { key: "03-07", name: "Иоанна Парусникова", kind: "saint", desc: "Священномученик Иоанн родился 2 июня 1869 года в селе Захарово Клинского уезда Московской губернии в семье диакона Василия Парусникова. В 1890 году он окончил Московскую Духовную семинарию и был учителем в церковноприходских школах." },
  { key: "03-07", name: "Сергия Белокурова", kind: "saint", desc: "Священномученик Сергий родился 24 сентября 1880 года в городе Волоколамске Московской губернии в семье псаломщика Ивана Белокурова, служившего в городском Воскресенском соборе." },
  { key: "03-07", name: "Андрея Ясенева", kind: "saint", desc: "Священномученик Андрей родился 12 августа 1868 года в селе Ясенок Рязанской губернии в семье диакона Иоанна Ясенева. Окончив в 1889 году Рязанскую Духовную семинарию, Андрей Иванович был рукоположен во диакона, а в 1891 году во священника к" },
  { key: "03-07", name: "Павла Смирнова", kind: "saint", desc: "Священномученик Павел родился 6 декабря 1877 года в селе Тишково Серпуховского уезда Московской губернии в семье священника Федора Константиновича Смирнова, служившего здесь в храме Преображения Господня." },
  { key: "03-07", name: "прмчч. Сергия", kind: "saint", desc: "Преподобномученик Сергий родился 23 января 1884 года в селе Чертаново Осташевской волости Волоколамского уезда Московской губернии в семье крестьянина Василия Букашкина и в крещении был наречен Иоанном." },
  { key: "03-07", name: "Антипы", kind: "saint", desc: "Преподобномученик Антипа родился 3 августа 1870 года в селе Братки Борисоглебского уезда Тамбовской губернии в семье крестьянина Петра Кириллова и в крещении был наречен Антонием." },
  { key: "03-07", name: "прмц. Параскевы Макаровой, послушницы", kind: "saint", desc: "Преподобномученица Параскева родилась в 1878 году в деревне Макарово Волоколамского уезда Московской губернии в семье Космы Макарова, который, кроме крестьянского хозяйства, имел небольшую торговлю в Москве и в деревне." },
  { key: "03-07", name: "мчч. Стефана Франтова", kind: "saint", desc: "Мученик Стефан родился 17 декабря 1877 года в селе Нащекино Бронницкого уезда Московской губернии в семье крестьянина Федора Франтова. Образование Степан получил в сельской школе и некоторое время помогал отцу управляться с крестьянским хозяйством, а затем переехал в Москву и стал работать экспедитором при складе." },
  { key: "03-07", name: "Николая Некрасова", kind: "saint", desc: "Николай Некрасов родился в 1872 году. Свою жизнь он посвятил служению Церкви, подвизаясь в должности псаломщика. 7 марта 1938 года псаломщик Николай Некрасов принял мученическую кончину от рук богопротивной власти в возрасте 66 лет." },
  { key: "03-08", name: "Свт. Григория Паламы, архиепископа Фессалонитского", kind: "saint", desc: "Святитель Григорий Палама, архиепископ Солунский, родился в 1296 году в Малой Азии. Во время турецкого нашествия семья бежала в Константинополь и нашла приют при дворе Андроника II Палеолога (1282–1328)." },
  { key: "03-08", name: "Сщмч. Поликарпа, епископа Смирнского", kind: "saint", desc: "Святитель Поликарп, епископ Смирнский, родился около 80 г., жил в Малой Азии, в г. Смирне. Рано оставшись сиротой, он был воспитан, по указанию Ангела, благочестивой вдовой Каллистой." },
  { key: "03-08", name: "обретение мощей блж. Матроны Московской", kind: "saint", desc: "8 марта (переходящая) - Обр е тение мощей. 8 марта / 23 февраля в невисокосный год, 7 марта / 23 февраля в високосный год Родилась блаженная Матрона (Матрона Димитриевна Никонова) в 1881 году в селе Себино Епифанского уезда (ныне Кимовского района) Тульской губернии.", lifeId: "matrona" },
  { key: "03-08", name: "Прп. Поликарпа Брянского, игумена", kind: "saint", desc: "Как предполагают в миру был князем Петром Ивановичем Борятинским, потомком святого Михаила, князя Черниговского (&dagger; 1245, память 20 сентября/З октября)." },
  { key: "03-08", name: "прп. Зиновия (в схиме Серафима) (Мажуги), митрополита Тетрицкаройского", kind: "saint", desc: "Прп. Зиновий (Мажуга, 1896–1985), митрополит ‒ грузинский иерарх русского происхождения, духовный воспитанник Глинской пустыни. После закрытия обители в 1922 году переехал в Грузию." },
  { key: "03-08", name: "прп. Александра Константинопольского, начальника обители «Неусыпающих»", kind: "saint", desc: "Прп. Александр, основатель монастыря \"Неусыпающих\", начал свой путь как военный, но оставил мир ради монашества. После 4 лет послушания в сирийской обители и 7 лет пустынножительства с одним Евангелием, он обратил ко Христу градоначальника " },
  { key: "03-08", name: "Собор всех преподобных отцов Киево-Печерских", kind: "feast", desc: "Во 2-ю неделю Великого поста празднуется Собор всех преподобных отцов Киево-Печерских, почивающих в Ближних (преподобного Антония) и Дальних (преподобного Феодосия) пещерах." },
  { key: "03-08", name: "Сщмчч. Павла Кушникова", kind: "saint", desc: "Священник Павел Александрович Кушников [1] родился 16 декабря 1880 года в семье священника Спасо-Преображенской Моденской церкви Устюженского уезда Новгородской губернии." },
  { key: "03-08", name: "Алексия Никольского", kind: "saint", desc: "Священномученик Алексий родился 10 февраля 1877 года в селе Генино Серпуховского уезда Московской губернии в семье священника Иоанна Никольского, служившего в храме святых благоверных князей Бориса и Глеба." },
  { key: "03-08", name: "Николая Дмитрова", kind: "saint", desc: "Священномученик Николай родился 14 мая 1878 года в селе Кунцево Московской губернии в семье священника Лавра Дмитрова, болгарина по происхождению. В 1900 году Николай окончил Московскую Духовную семинарию и стал работать учителем в селе Кунцево." },
  { key: "03-08", name: "Михаила Ражкина", kind: "saint", desc: "Священномученик Михаил родился 1 октября 1871 года в селе Елань Саратовской губернии в семье крестьянина Степана Ражкина. Со временем семья переехала жить в город, и Михаил окончил 4-е городское училище." },
  { key: "03-08", name: "мч. Сергия Бородавкина", kind: "saint", desc: "Мученик Сергий (Сергей Матвеевич Бородавкин) родился 29 декабря 1878 года в городе Красный Холм Тверской губернии. Окончил городское училище. Он был купцом первой гильдии и почетным гражданином города." },
  { key: "03-09", name: "Первое (IV) и второе (452) обретение главы Пророка, Предтечи и Крестителя Господня Иоанна", kind: "feast", desc: "После усекновения главы Пророка, Предтечи и Крестителя Господня Иоанна тело его было погребено учениками в самарийском городе Севастии, а честная глава сокрыта Иродиадой в бесчестном месте.", lifeId: "ioann-predtecha" },
  { key: "03-09", name: "Прп. Еразма Печерского, в Ближних пещерах", kind: "saint", desc: "О преподобном Еразме Печерском святитель Симон, епископ Владимирский (&dagger; 1226, память 10 мая), писал другу своему преподобному Поликарпу (&dagger; 1182; память 24 июля): &quot;Был в Печерском монастыре черноризец Еразм." },
  { key: "03-10", name: "Свт. Тарасия, архиепископа Константинопольского", kind: "saint", desc: "Святитель Тарасий, патриарх Константинопольский, происходил из знатного рода, родился и был воспитан в Константинополе, где получил хорошее образование." },
  { key: "03-10", name: "Свт. Сильвестра (Ольшевского), архиепископа Омского, исп.", kind: "saint", desc: "Сщисп. Сильвестр (Ольшевский, 1860-1920) родился в семье диакона, окончил Киевскую духовную академию, занимался миссионерской и педагогической деятельностью." },
  { key: "03-10", name: "сщмч. Александра Виноградова, пресвитера", kind: "saint", desc: "Священномученик Александр родился 30 августа 1883 года в деревне Станинская Егорьевского уезда Рязанской губернии в семье крестьянина Федора Виноградова." },
  { key: "03-10", name: "прмц. Мстиславы (Фокиной), монахини", kind: "saint", desc: "Преподобномученица Мстислава родилась в 1895 году в деревне Малое Уварово Коломенского уезда Московской губернии в семье рабочего коломенского завода Семена Фокина и в крещении была наречена Марией." },
  { key: "03-10", name: "сщмч. Николая Троицкого, пресвитера", kind: "saint", desc: "Священномученик Николай родился в 1895 году в селе Выползово Курмышского уезда Симбирской губернии (ныне Порецкого района Чувашии) в семье диакона Димитрия Троицкого." },
  { key: "03-11", name: "Свт. Порфирия, архиепископа Газского", kind: "saint", desc: "Святитель Порфирий, архиепископ Газский, родился около 346 года в Фессалониках, в Македонии. Родители его были людьми состоятельными, и это позволило святителю Порфирию получить хорошее образование." },
  { key: "03-11", name: "Прп. Севастиана Сохотского, Пошехонского", kind: "saint", desc: "Преподобный Севастиан Сохотский, Пошехонский (&dagger; ок. 1500/1542 [1] ) основал монастырь в честь Преображения Господня на реке Сохоти в 90 верстах от города Романова (ныне Тутаев Ярославской области)." },
  { key: "03-11", name: "мч. Севастиана", kind: "saint", desc: "Мученик Севастиан Римский (&dagger; ок. 66) был градоначальником Атталии. При встрече со святым Виктором, сыном мученицы Фотины Самаряныни , сказал ему: &quot;Я знаю достоверно, что ты, твоя мать и твой брат - последователи учения Христа." },
  { key: "03-11", name: "Сщмч. Михаила Лисицына, пресвитера", kind: "saint", desc: "Священник Михаил Михайлович Лисицын родился 19 октября 1862 года в селе Екшур Рязанского уезда Рязанской губернии в семье священника. По окончании Рязанской духовной семинарии в 1883 году поступил на службу преподавателем в сельскую Задне-Пилевскую школу Рязанской губернии." },
  { key: "03-11", name: "сщмч. Петра Варламова, пресвитера", kind: "saint", desc: "Священномученик Петр родился в 1897 году в селе Дияшево Белебеевского уезда Уфимской губернии в бедной крестьянской семье Иакова и Елены Варламовых. Отец умер, когда Петру было девять лет, и мать сама воспитывала трех сыновей и дочь, и он с детства узнал бедность и лишения." },
  { key: "03-11", name: "сщмч. Сергия Воскресенского, пресвитера", kind: "saint", desc: "Священномученик Сергий родился 29 июля 1890 года в селе Дьякове [1] Московского уезда Московской губернии в семье священника Сергия Воскресенского и его супруги Евдокии Сергеевны." },
  { key: "03-11", name: "сщмч. Иоанна (Пашина), епископа Рыльского,", kind: "saint", desc: "Священномученик Иоанн родился 8 мая 1881 года в городе Петрикове Мозырского уезда Минской губернии в семье священника Димитрия Пашина и его супруги Надежды, дочери священника Никольской церкви в местечке Скрыгалове Василия Завитневича." },
  { key: "03-11", name: "Иоанна Дунаева, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился в 1885 году в селе Васильевское Угличского уезда Ярославской губернии в семье псаломщика Александра Дунаева. Иван окончил четыре класса городского училища и во времена гонений служил псаломщиком в Благовещенской церкви в селе Благовещенье Тутаевского района [1] ." },
  { key: "03-11", name: "прмц. Анны (Благовещенской), монахини", kind: "saint", desc: "В начале XX века из многих монастырей Вологодского края в Грязовецком уезде особенно славен был духовной жизнью своих насельников Павло-Обнорский Троицкий монастырь, расположенный в пятнадцати верстах от города Грязовца на левом берегу реки Нурмы." },
  { key: "03-12", name: "Прп. Прокопия Декаполита, исп.", kind: "saint", desc: "Преподобноисповедник Прокопий родился в стране Декаполитской (т. е. Десятиградии), на восток от Галилейского озера. Оставив суетный мир, Прокопий принял в одной обители иноческий чин и проводил все время в молитве и посте." },
  { key: "03-12", name: "Прп. Тита, пресвитера Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Тит был священноинок Киевского Печерского монастыря, известный своим чрезвычайно миролюбивым ко всем отношением. Особенно полюбил Тит миролюбие благодаря следующим обстоятельствам." },
  { key: "03-12", name: "прп. Тита Печерского, бывшего воина, в Дальних пещерах", kind: "saint", desc: "Почивает в Дальних (Феодосиевых) пещерах. В миру был воином и в одной из битв был тяжело ранен в голову. После выздоровления преподобный Тит пришел подвизаться в Киево-Печерский монастырь, где оплакивал грехи свои." },
  { key: "03-12", name: "прп. Фалалея Сирийского", kind: "saint", desc: "Преподобный Фалалей жил в V веке, родом был из Киликии (Малая Азия), принял иночество в обители Саввы Освященного и там же был рукоположен во пресвитера." },
  { key: "03-12", name: "Сщмч. Сергия Увицкого, пресвитера", kind: "saint", desc: "Сергей Александрович Увицкий родился в 1881 году в селе Хлебниково Вятской губернии в семье учителя, ставшего позднее священнослужителем. Образование будущий священномученик получил в Казанской Духовной Академии, по окончании которой преподавал в Могилевской Духовной Семинарии." },
  { key: "03-12", name: "мч. Михаила Маркова", kind: "saint", desc: "Мученик Михаил родился 8 ноября 1884 года в селе Глухино Клинского уезда Московской губернии в семье крестьянина Дмитрия Маркова. Родители Михаила занимались крестьянским хозяйством и разрабатывали лесные делянки, изготовляя пиломатериалы." },
  { key: "03-13", name: "Прп. Василия Декаполита, исп.", kind: "saint", desc: "Преподобный Василий исповедник был иноком и пострадал в царствование иконоборца Льва Исавра (717–741). Когда началось гонение на почитателей святых икон, святой Василий вместе со своим сподвижником преподобным Прокопием (память 27 февраля) " },
  { key: "03-13", name: "сщмч. Арсения (Мацеевича), митрополита Ростовского", kind: "saint", desc: "Священномученик Арсений, митрополит Ростовский (в миру Александр Мацеевич) был последним противником церковной реформы Петра I. Он родился в 1697 (по другим данным, в 1696) году во Владимире-Волынском в семье православного священника, ведшего свой род из польской шляхты." },
  { key: "03-13", name: "Прп. Кассиана (Иоанна Кассиана) Римлянина, иеромонаха", kind: "saint", desc: "Преподобный Иоанн Кассиан Римлянин по месту рождения и языку, на котором писал, принадлежал Западу, но духовной родиной святого всегда был православный Восток." },
  { key: "03-13", name: "Блж. Николая Саллоса, Христа ради юродивого, Псковского", kind: "saint", desc: "Был родом из Псковской земли. Его ходатайством перед царем Иоанном Грозным в 1570 г. был спасен от разгрома опальный город Псков. Скончался святой Николай 28 февраля 1576 г." },
  { key: "03-13", name: "сщмч. Протерия, патриарха Александрийского", kind: "saint", desc: "Во время патриаршества Диоскора (444–451), который был последователем монофизитского лжеучения Евтихия, в Александрии жил пресвитер Протерий, который бесстрашно обличал еретиков и исповедовал православную веру." },
  { key: "03-13", name: "сщмч. Нестора, епископа Магиддийского", kind: "saint", desc: "Священномученик Нестор, епископ Магиддийский, в гонение на христиан от римского императора Декия (249–251), в 250 году, был взят в своем доме во время молитвы." },
  { key: "03-13", name: "прп. Иоанна, нареченного Варсонофием, епископа Дамасского", kind: "saint", desc: "Преподобный Иоанн, нареченный Варсонофием, был родом из Палестины, 18-ти лет воспринял он Святое Крещение, а вскоре и иноческий постриг. За свою подвижническую жизнь преподобный Иоанн был рукоположен во епископа города Дамаска." },
  { key: "03-13", name: "прп. Феоктириста (Феостирикта) Медикийского, исп.", kind: "saint", desc: "Святой Феоктирист (Феостирикт), игумен Пеликитский, пострадал за иконопочитание при нечестивом императоре Константине Копрониме (741–775). Вместе с ним были подвергнуты пыткам святой Стефан Новый (память 28 ноября) и другие благочестивые иноки." },
  { key: "03-13", name: "Девпетерувская", year: "1392", kind: "saint", desc: "Икона Богородицы Девпетерувская [Девпетерусская] – чудотворный образ «Умиление», явленный в 1392 г.; происхождение названия и подробности явления иконы неизвестны." },
  { key: "03-14", name: "Прмц. Евдокии Илиопольской, игумении", kind: "saint", desc: "Святая Евдокия была самарянкой по рождению. Жила она в Илиополе Финикийском во времена Римского императора Траяна (98–117 гг.). Отличаясь в молодости редкой красотой и стройностью, Евдокия вела греховную жизнь, торгуя своим телом." },
  { key: "03-14", name: "Прп. Мартирия Зеленецкого", kind: "saint", desc: "Родом из Великих Лук, Псковской губернии, святой с юных лет подвизался в Великолуцкой Сергиевой обители. Желая уединенных подвигов, он поселился на острове Зеленом и основал там монастырь." },
  { key: "03-14", name: "мц. Антонины Никейской", kind: "saint", desc: "Св. мц. Антонина Никейская пострадала при императоре Максимиане (начало IV в.). После жестоких пыток, включая раскалённый одр, была утоплена в озере, оставшись верной Христу." },
  { key: "03-14", name: "прп. Домнины Сирийской", kind: "saint", desc: "Преподобная Домнина Сирийская была ученицей святого Марона (память 14 февраля). В саду своей матери преподобная устроила хижину, крытую соломой, и подвизалась в ней, принимая в пищу только размоченную в воде чечевицу." },
  { key: "03-14", name: "Сщмчч. Василия Никитского", kind: "saint", desc: "Священномученик Василий родился 3 января 1889 года в селе Александровском Волоколамского уезда Московской губернии в семье псаломщика Петра Никитского и его жены Екатерины, у которых было девять детей." },
  { key: "03-14", name: "Петра Любимова", kind: "saint", desc: "Священномученик Петр родился 6 января 1867 года в селе Свитино Подольского уезда Московской губернии в семье псаломщика Павла Петровича Любимова. В 1882 году Петр окончил Перервинское духовное училище, в 1888 году — Московскую Духовную семинарию." },
  { key: "03-14", name: "Иоанна Стрельцова", kind: "saint", desc: "Священномученик Иоанн родился 21 мая 1872 года в селе Гридино Бронницкого уезда Московской губернии в семье псаломщика Лаврентия Ивановича Стрельцова. В 1888 году Иван окончил Коломенское духовное училище, а в 1894 году — Московскую Духовную семинарию." },
  { key: "03-14", name: "Вениамина Фаминцева", kind: "saint", desc: "Священномученик Вениамин родился 19 января 1873 года в городе Коломне Московской губернии в семье священника Иоанна Фаминцева и его супруги Марии. Образование Вениамин получил в Московской Духовной семинарии, которую окончил в 1893 году." },
  { key: "03-14", name: "Михаила Букринского", kind: "saint", desc: "Священномученик Михаил родился 19 ноября 1869 года в селе Булыгино Зарайского уезда Рязанской губернии в семье псаломщика Алексия Букринского. В 1890 году Михаил окончил Рязанскую Духовную семинарию и в 1894 году был рукоположен во священника к Троицкой церкви в селе Зименки Зарайского уезда." },
  { key: "03-14", name: "прмч. Антония (Коржа), иеродиакона", kind: "saint", desc: "Преподобномученик Антоний родился в 1888 году в селе Рубановке Мелитопольского уезда Таврической губернии в семье крестьянина Агафона Коржа. Он окончил церковноприходскую школу и, как многие юноши из благочестивых крестьянских семей, предпр" },
  { key: "03-14", name: "прмцц. Анны Макандиной", kind: "saint", desc: "Преподобномученица Анна родилась 5 ноября 1892 года в селе Константиново Александровского уезда Владимирской губернии в семье крестьянина Алексея Макандина." },
  { key: "03-14", name: "Дарии Зайцевой", kind: "saint", desc: "Преподобномученица Дария родилась в 1870 году в селе Богослово Рязанского уезда Рязанской губернии в семье крестьянина Петра Зайцева. Когда Дарье исполнилось девятнадцать лет, она поступила послушницей в Борисоглебский Аносин монастырь Звенигородского уезда Московской губернии." },
  { key: "03-14", name: "Евдокии Архиповой", kind: "saint", desc: "Преподобномученица Евдокия родилась в 1886 году в селе Горетово Луховицкого уезда Рязанской губернии в семье крестьянина Сергея Архипова. В 1902 году она поступила послушницей в старинный Казанский монастырь в городе Рязани, где в то время было более трехсот пятидесяти насельниц." },
  { key: "03-14", name: "Ольги Жильцовой", kind: "saint", desc: "Преподобномученица Евдокия родилась в 1886 году в селе Горетово Луховицкого уезда Рязанской губернии в семье крестьянина Сергея Архипова. В 1902 году она поступила послушницей в старинный Казанский монастырь в городе Рязани, где в то время было более трехсот пятидесяти насельниц." },
  { key: "03-15", name: "Иконы Божией Матери, именуемой «Державная»", year: "1917", kind: "icon", desc: "Икона Божией Матери, именуемая «Державная», явила себя русскому православному народу 2/15 марта 1917 года — в день отречения от престола императора Николая II, будущего царственного страстотерпца, — в селе Коломенском близ Москвы." },
  { key: "03-15", name: "Сщмч. Феодота, епископа Киринейского", kind: "saint", desc: "Священномученик Феодот, родом из малоазийской Галатии, был епископом города Киринии на Кипре. Во время гонения на христиан нечестивого Ликиния (307–324) святой Феодот открыто проповедовал Христа, призывая язычников оставить идолослужение и обратиться к Истинному Богу." },
  { key: "03-15", name: "свт. Арсения, епископа Тверского", kind: "saint", desc: "Свт. Арсений, епископ Тверской, принял постриг в Киево-Печерской лавре, где выделялся строгой подвижнической жизнью. В 1390 г., несмотря на первоначальный отказ, был назначен на Тверскую кафедру, где прекратил княжеские междоусобицы." },
  { key: "03-15", name: "Мц. Евфалии Леентинской (Сицилийской)", kind: "saint", desc: "Святая мученица Евфалия жила с матерью и братом в городе Леонтине на острове Сицилия. Мать Евфалии, язычница, долго и тяжело болела. Однажды ей во сне явились мученики Алфий, Филадельф и Киприан (память 10 мая) и сказали ей, что она исцелится, если уверует во Христа." },
  { key: "03-15", name: "мч. Троадия Неокесарийского", kind: "saint", desc: "Святой мученик Троадий пострадал за Христа в Неокесарии Понтийской при императоре Декии (249–251), претерпев жесточайшие мучения. О его страдании свидетельствует святой Григорий Неокесарийский (память 17 ноября), предсказавший его мученический подвиг." },
  { key: "03-15", name: "прп. Агафона Скитского (Египетского)", kind: "saint", desc: "Преподобный Агафон Египетский, современник преподобного Макария Великого (память 19 января), подвизался в Скитской пустыне в Египте. Он отличался необыкновенным смирением, считая себя грешнейшим из людей." },
  { key: "03-15", name: "мчч. 440 Италийских", kind: "saint", desc: "Италийские мученики – 440 человек – отказались участвовать в идолослужении и были зарублены лангобардами (германское племя) в 579 году. Среди погибших за веру известны имена пресвитера Санктула и отшельника Госпиция." },
  { key: "03-16", name: "Евтропия", kind: "saint", desc: "Святые мученики Евтропий, Клеоник и Василиск пострадали в городе Амасии Понтийской (Малая Азия) около 308 года. Братья Евтропий и Клеоник и племянник святого великомученика Феодора Тирона (память 17 февраля) Василиск были друзьями." },
  { key: "03-16", name: "Клеоника", kind: "saint", desc: "Святые мученики Евтропий, Клеоник и Василиск пострадали в городе Амасии Понтийской (Малая Азия) около 308 года. Братья Евтропий и Клеоник и племянник святого великомученика Феодора Тирона (память 17 февраля) Василиск были друзьями." },
  { key: "03-16", name: "Василиска Команского", kind: "saint", desc: "Племянник св. Феодора Тирона. По пути на казнь в медных сапогах с гвоздями (которые вонзались при шаге) молился у сухого дерева — произошло землетрясение, и из скалы забил источник." },
  { key: "03-16", name: "Прп. Пиамы девы", kind: "saint", desc: "Преподобная Пиама подвизалась недалеко от Александрии. В доме своей матери святая жила, как в затворе: ни с кем не виделась, пищу принимала через день, после молитвы пряла лен." },
  { key: "03-16", name: "Прмц. Марфы Ковровой, послушницы", kind: "saint", desc: "Марфа Степановна Коврова родилась в 1887 году в селе Галыгино Коробовского района Московской области и происходила из крестьянской семьи. Решив посвятить свою жизнь служению Богу, она стала послушницей Александро-Мариинского женского монастыря в деревне Евлево Егорьевского уезда Рязанской губернии." },
  { key: "03-16", name: "мч. Михаила Строева", kind: "saint", desc: "Мученик Михаил родился 6 сентября 1876 года в городе Воскресенске [1] Звенигородского уезда Московской губернии в семье Степана Строева — бывшего крепостного живописца, приписанного к Новоиерусалимскому монастырю." },
  { key: "03-16", name: "Волоколамская", year: "1572", kind: "saint", desc: "Нет на Русской земле уголка, где бы ни проявилась чудотворная сила от какой-либо иконы Богоматери. Иосифо-Волоколамский монастырь – не исключение. Именно здесь во второй половине XVI века была явлена икона Пресвятой Богородицы, которая стала именоваться Волоколамской." },
  { key: "03-17", name: "Прп. Герасима, иже на Иордане", kind: "saint", desc: "Был родом из г. Ликии (Каппадокия, Малая Азия). Уже в юности он решил оставить мирскую жизнь и посвятить себя служению Богу. Приняв монашество, он ушел в Египет, в Фиваидскую пустыню." },
  { key: "03-17", name: "прп. Герасима Вологодского", kind: "saint", desc: "Монашеское пострижение принял в Киевской Гнилецкой Успенской обители, где проводил дни свои в непрестанных трудах и глубокой сердечной молитве. Из послушания братии он принял сан иеромонаха." },
  { key: "03-17", name: "блгв. кн. Даниила Московского", kind: "saint", desc: "Св. блгв. кн. Даниил Московский (1261–1303) ‒ младший сын св. Александра Невского, основатель Московского княжества. Прославился благочестием, миротворчеством и мудрым правлением." },
  { key: "03-17", name: "Блгв. кн. Василия (Василько) Ростовского", kind: "saint", desc: "Принадлежал к славному в русской истории роду суздальских Мономашичей. Его прадед – Юрий Долгорукий, дед – великий князь Всеволод III Большое Гнездо (&dagger; 1212 г.), брат святого Андрея Боголюбского (память 4/17 июля), наследник и продолжатель его дела." },
  { key: "03-17", name: "прмч. Иоасафа Снетогорского, Псковского", kind: "saint", desc: "Святые преподобномученики Василий Мирожский и Иоасаф Снетногорский пострадали от немцев в двух древнейших монастырях Пскова в XIII столетии. Преподобный Василий управлял Спасо-Преображенской Мирожской обителью, основанной около 1156 года св" },
  { key: "03-17", name: "прп. Иакова постника", kind: "saint", desc: "Преподобный Иаков постник подвизался недалеко от финикийского города Порфириона. Пятнадцать лет он жил в пещере, предаваясь иноческим подвигам, и получил от Господа дар чудотворения." },
  { key: "03-17", name: "блгв. кн. Вячеслава Чешского", kind: "saint", desc: "Блгв. князь Вячеслав Чешский (†935) был внуком св. княгини Людмилы. Воспитанный в христианской вере, он получил блестящее образование. Став князем в 18 лет, правил мудро и справедливо, заботился о распространении христианства: строил храмы, выкупал детей из рабства для христианского воспитания." },
  { key: "03-17", name: "свт. Григория, епископа Констанции Кипрской", kind: "saint", desc: "Святой Григорий, епископ города Констанции, что на острове Кипре, скончался в мире, год кончины неизвестен. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите к" },
  { key: "03-17", name: "Сщмч. Александра Лихарева, пресвитера", kind: "saint", desc: "Священномученик Александр родился 22 января 1876 года в селе Синьково Софьинской волости Бронницкого уезда Московской губернии в семье священника Петра Лихарева." },
  { key: "03-18", name: "Мч. Конона Исаврийского", kind: "saint", desc: "Святой мученик Конон Исаврийский родился в Вифании, селении, расположенном рядом с малоазийским городом Исаврией, жители которого приняли христианскую веру от апостола Павла." },
  { key: "03-18", name: "прмч. Адриана Пошехонского, Ярославского, игумена", kind: "saint", desc: "Был учеником преподобного Корнилия Комельского, вначале подвизался в Вологодском Комельском монастыре и был искусным иконописцем. По благословению игумена 13 сентября 1540 г., взяв икону Успения Пресвятой Богородицы , преподобный Адриан вме" },
  { key: "03-18", name: "мч. Онисия Усуровского (Исаврийского)", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "03-18", name: "мч. Конона Мандонского (Памфилийского), градаря (огородника)", kind: "saint", desc: "Святой мученик Конон градарь родился в Назарете Галилейском, а жил в городе Мандоне, где занимался огородничеством. Он был богобоязненным человеком, добрым, простосердечным, незлобивым." },
  { key: "03-18", name: "мц. Ираиды", kind: "saint", desc: "Архелай и 152 мученика Антинойских, из которых по именам известны Фотий и Кирилл (пам. греч. 4, 5 и 20 марта). Когда корабль, перевозивший закованных в цепи мучеников, среди которых были мужчины и женщины, миряне, монахи, диаконы и иереи, п" },
  { key: "03-18", name: "мч. Евлогия, иже в Палестине", kind: "saint", desc: "Святой мученик Евлогий был родом из Палестины. После смерти родителей-язычников он раздал свое имущество бедным, а сам стал странником и ходил по Палестине, обращая язычников в христианство." },
  { key: "03-18", name: "мч. Евлампия Палестинского", kind: "saint", desc: "Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Сообщить об ошибке' или Ctrl+Enter." },
  { key: "03-18", name: "прп. Марка Нитрийского", kind: "saint", desc: "Преподобный Марк подвизался в V веке в Нитрийской пустыне (Нижний Египет). С юности его любимым занятием было чтение Священного Писания. Есть свидетельства, что он знал наизусть всю Библию." },
  { key: "03-18", name: "прп. Исихия Вифинского", kind: "saint", desc: "Преподобный Исихий Постник родился в приморском городе Адрании в Вифинии. С юности воспитанный в благочестии, он оставил родной дом и подвизался в пустынном месте на горе Маионис." },
  { key: "03-18", name: "Сщмч. Николая Покровского, пресвитера", kind: "saint", desc: "Николай Сергеевич Покровский родился в 1864 году в семье священника. Имея искреннее желание продолжить семейную традицию и посвятить свою жизнь служению Церкви Христовой, Николай поступил в Симбирскую Духовную семинарию, которую, будучи человеком незаурядных способностей, окончил в 1889 году по первому разряду." },
  { key: "03-18", name: "сщмч. Иоанна Миротворцева, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 25 марта 1881 года в селе Елшанка Саратовского уезда Саратовской губернии в семье крестьянина Николая Миротворцева. По окончании Саратовской Духовной семинарии он был рукоположен во священника ко храму в селе Вязьмино Саратовского уезда, где прослужил девять лет." },
  { key: "03-18", name: "прмчч. Мардария (Исаева), иеромонаха", kind: "saint", desc: "Преподобномученик Мардарий родился 4 января 1886 года в деревне Савостино Микулинской волости Старицкого уезда Тверской губернии в крестьянской семье и в крещении был наречен Михаилом." },
  { key: "03-18", name: "Феофана (Графова), иеродиакона", kind: "saint", desc: "Преподобномученик Феофан родился 6 января 1874 года в слободе Никитской Переславского уезда Владимирской губернии в семье крестьянина Федора Графова и в крещении был наречен Феодосием." },
  { key: "03-18", name: "Обретение мощей свт. Луки (Войно-Ясенецкого), исп., архиепископа Симферопольского и Крымского", kind: "saint", desc: "Свт. Лука (Войно-Ясенецкий, 1877–1961) – архиепископ, выдающийся хирург и профессор медицины. Родился в Керчи. Сочетал врачебную практику с пастырским служением." },
  { key: "03-19", name: "прп. Иова, в схиме Иисуса, Анзерского", kind: "saint", desc: "Преподобный Иов (в схиме Иисус) Анзерский родился в 1635 году в Москве, стал священником и славился благочестием, милосердием и даром молитвы. Став духовником Петра I, был оклеветан и сослан на Соловки, где принял монашество." },
  { key: "03-19", name: "Равноап. царицы Елены, обретение ею во Иерусалиме Честного Креста и гвоздей", kind: "saint", desc: "Мать равноап. императора Константина Великого. В 80 лет совершила паломничество в Иерусалим, где по её указанию начались раскопки на Голгофе. В 326 году чудесным образом обрела Животворящий Крест Господень." },
  { key: "03-19", name: "прп. Аркадия Кипрского", kind: "saint", desc: "Преподобный Аркадий с юности всецело посвятил себя иноческим подвигам. Святой подвизался на острове Кипр во времена императора Константина Великого (306–337)." },
  { key: "03-19", name: "прп. Фридолина Зекингенского", kind: "saint", desc: "Преподобный Фридолин Зекингенский (&dagger; 538), по преданию, происходил из благородного ирландского семейства. В конце V века он прибыл из Ирландии в Пуатье, так как ему было видение святителя Илария Пиктавийского (память 13/26 января – галл., греч., румын.), в котором тот попросил Фридолина найти его мощи." },
  { key: "03-19", name: "Ченстоховская", kind: "saint", desc: "Ченстоховская икона Божией Матери относится, по преданию, к тем 70-ти иконам Пресвятой Богородицы, которые написал святой евангелист Лука (память 18 октября)." },
  { key: "03-19", name: "Шестоковская", kind: "saint", desc: "Шестоковская, или Шелтомежская, икона Божией Матери явилась в середине XVIII столетия в Москве , в семье некоего Николая Димитриевича Скрипицына. Однажды служанка, которую называли блаженной, во сне увидела, что в печной трубе сокрыта икона Пресвятой Богородицы." },
  { key: "03-19", name: "Благодатное Небо", kind: "saint", desc: "Чудотворная икона Божией Матери, именуемая «Благодатное Небо», находится в иконостасе Московского Архангельского собора Кремля по левую сторону от царских врат." },
  { key: "03-20", name: "Прп. Павла Препростого", kind: "saint", desc: "Прп. Павел Препростый, живший в IV веке, получил свое имя за незлобие и простосердечие. В возрасте 60 лет, узнав о неверности жены, он оставил мир и пришел в пустыню к прп." },
  { key: "03-20", name: "свт. Павла исп., епископа Прусиадского", kind: "saint", desc: "Святитель Павел Исповедник был епископом в городе Прусиаде (провинция Вифиния в Малой Азии) в то время, когда против веры Христовой неистовствовали иконоборцы." },
  { key: "03-20", name: "прп. Емилиана Италийского", kind: "saint", desc: "Преподобный Емилиан Италийский (в мире Викторин) был родом римлянин, до старости вел греховную жизнь. Наконец, раскаявшись, он удалился в монастырь, принял монашество с именем Емилиан и остаток дней своих смиренно служил Богу, удивляя братию своим безропотным послушанием и суровым постничеством." },
  { key: "03-20", name: "Сщмч. Николая Розова, пресвитера", kind: "saint", desc: "Священномученик Николай родился в 1870 году в селе Иваньково Ростовского уезда Ярославской губернии в семье священника Николая Розова. По окончании Ярославской Духовной семинарии Николай Николаевич был рукоположен во священника ко храму в с" },
  { key: "03-20", name: "прмч. Нила (Тютюкина), иеромонаха", kind: "saint", desc: "Преподобномученик Нил родился 4 мая 1871 года в селе Ольявидово Дмитровского уезда Московской губернии в семье крестьян Федора и Анны Тютюкиных и в крещении был наречен Николаем." },
  { key: "03-20", name: "Екатерины Константиновой", kind: "saint", desc: "Преподобномученица Екатерина родилась в 1887 году в деревне Саврасово Солнечногорской волости Клинского уезда Московской губернии в семье зажиточного крестьянина Григория Константинова, владельца столярной мастерской и чайной, при которой была мелочная лавка." },
  { key: "03-20", name: "Антонины Новиковой", kind: "saint", desc: "Преподобномученица Антонина родилась в 1880 году в селе Горки Зарайского уезда Рязанской губернии в семье Андрея Новикова, владельца кирпичного завода, имевшего в своей собственности землю и четырнадцать дач, которые сдавались внаем." },
  { key: "03-20", name: "Надежды Кругловой", kind: "saint", desc: "Преподобномученица Антонина родилась в 1880 году в селе Горки Зарайского уезда Рязанской губернии в семье Андрея Новикова, владельца кирпичного завода, имевшего в своей собственности землю и четырнадцать дач, которые сдавались внаем." },
  { key: "03-20", name: "Ксении Петрухиной", kind: "saint", desc: "Преподобномученицы Ксения и Анна подвизались в Успенском Брусенском монастыре в городе Коломне Московской губернии. Преподобномученица Ксения родилась в 1897 году в селе Чанки Коломенского уезда Московской губернии в семье крестьянина Семена Петрухина.", lifeId: "kseniya" },
  { key: "03-20", name: "Анны Гороховой", kind: "saint", desc: "Преподобномученицы Ксения и Анна подвизались в Успенском Брусенском монастыре в городе Коломне Московской губернии. Преподобномученица Ксения родилась в 1897 году в селе Чанки Коломенского уезда Московской губернии в семье крестьянина Семена Петрухина." },
  { key: "03-20", name: "Споручница грешных, в К о рце (Ровенск.) (1622) , в О дрине (Брянск.) (1843) и в Москве", year: "1848", kind: "saint", desc: "Икона Божией Матери &quot;Споручница грешных&quot; названа так по надписи, сохранившейся на иконе: &quot;Аз Споручница грешных к Моему Сыну...&quot;. Впервые этот образ прославился чудесами в Николаевском Одрине мужском монастыре Орловской губернии в середине 19-го столетия." },
  { key: "03-21", name: "Прп. Феофилакта исп., епископа Никомидийского", kind: "saint", desc: "Святой Феофилакт жил в Константинополе в VIII веке во время иконоборческой ереси. После смерти императора-иконоборца Льва IV Хазара (775–780) на престол вступил император Константин VI (780–797)." },
  { key: "03-21", name: "Лазаря", kind: "saint", desc: "Преподобный Лазарь был грек по национальности, родом из Константинополя , где и воспринял иноческое пострижение. В своем родном городе он принял иночество в Высокогорском монастыре от старца Афанасия Дискета – строителя многих обителей." },
  { key: "03-21", name: "Афанасия (XV) Муромских (Мурманских), Олонецких", kind: "saint", desc: "В обители преподобного Лазаря Муромского , или Мурманского, подвизался около половины XV столетия игумен Афанасий. К сожалению, не сохранилось никаких сведений о его богоугодной жизни." },
  { key: "03-21", name: "ап. от 70-ти Ерма (Ермы), епископа Филиппопольского", kind: "saint", desc: "Апостол от 70-ти Ерм, епископ Филиппопольский, упоминается апостолом Павлом в Послании к Римлянам (16:14). Был римским гражданином греческого происхождения, известен как автор книги «Пастырь»." },
  { key: "03-21", name: "сщмч. Феодорита, пресвитера Антиохийского", kind: "saint", desc: "Святой Феодорит был пресвитером и сосудохранителем соборной церкви в Антиохии. Эта церковь была построена и богато украшена императором, святым равноапостольным Константином Великим (306–337; память 21 мая), и его сыном Констанцием и называлась в народе &quot;Золотой церковью&quot;." },
  { key: "03-21", name: "прмч. Дометия Персиянина", kind: "saint", desc: "Время и место кончины неизвестны. Его память содержится в Синаксаре Константинопольской церкви конца X в. [1] , Типиконе Великой церкви IX–X вв. [2] , синаксарях семейства В [3] ." },
  { key: "03-21", name: "Сщмч. Иоанна Знаменского, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 8 марта 1868 года в селе Владыкино Санкт-Петербургского уезда Санкт-Петербургской губернии в семье священника Василия Знаменского." },
  { key: "03-21", name: "мч. Владимира Ушкова", kind: "saint", desc: "Мученик Владимир родился в 1885 году в селе Конобеево Бронницкого уезда Московской губернии в семье крестьянина Егора Ушкова. В свое время Владимир окончил сельскую школу и, придя в возраст, женился; у них с женой родилось четверо детей." },
  { key: "03-21", name: "Знамение Курская-Коренная", kind: "saint", desc: "Курская икона «Знамение» Божией Матери — одна из древнейших икон Русской Церкви. В ХIII веке, во время татарского нашествия, когда все Русское государство испытывало величайшее бедствие, город Курск, разоренный полчищами Батыя, пришел в запустение." },
  { key: "03-22", name: "Прп. Иоанна Лествичника, игумена Синайского", kind: "saint", desc: "Преподобный Иоанн Лествичник почитается Святой Церковью как великий подвижник и автор замечательного духовного творения, называемого &quot;Лествицей&quot;, поэтому преподобный и получил прозвание Лествичника." },
  { key: "03-22", name: "Мч. Урпасиана Никомидийского", kind: "saint", desc: "Святой мученик Урпасиан пострадал в городе Никомидии. Император Максимиан Галерий (305–311) жестоко преследовал христиан, служивших в его войске и при дворе." },
  { key: "03-22", name: "св. Кесария Назианзина, брата свт. Григория Богослова", kind: "saint", desc: "Святой Кесарий, брат святого Григория Богослова , жил долгое время при дворе императора Констанция (337 — ок. 361), был его другом и главным придворным врачом." },
  { key: "03-22", name: "прав. Тарасия Ликаонийского", kind: "saint", desc: "Время жизни этого святого неизвестно. По преданию, св. Тарасий с раннего детства полностью отдал себя служению Богу. Избранный сосуд благодати, он приносил в дар Господу посты, бдения, молитвы и слезы как благовонную жертву." },
  { key: "03-22", name: "Михаила Маслова", kind: "saint", desc: "Священномученик Михаил родился 8 июля 1874 года в селе Щеглятьево Старицкого уезда Тверской губернии [1] в семье псаломщика Григория Маслова. Михаил окончил церковноприходскую школу и один год учился в духовном училище, затем помогал отцу в крестьянском хозяйстве." },
  { key: "03-22", name: "Алексия Смирнова", kind: "saint", desc: "В январе 1938 года власти арестовали священников Ухтомского благочиния Московской епархии, и среди них протоиереев Сергия Лебедева, Сергия Цветкова и Алексия Смирнова и священника Димитрия Гливенко и заключили в Таганскую тюрьму в Москве." },
  { key: "03-22", name: "Димитрия Гливенко", kind: "saint", desc: "В январе 1938 года власти арестовали священников Ухтомского благочиния Московской епархии, и среди них протоиереев Сергия Лебедева, Сергия Цветкова и Алексия Смирнова и священника Димитрия Гливенко и заключили в Таганскую тюрьму в Москве." },
  { key: "03-22", name: "Сергия Лебедева", kind: "saint", desc: "В январе 1938 года власти арестовали священников Ухтомского благочиния Московской епархии, и среди них протоиереев Сергия Лебедева, Сергия Цветкова и Алексия Смирнова и священника Димитрия Гливенко и заключили в Таганскую тюрьму в Москве." },
  { key: "03-22", name: "Сергия Цветкова", kind: "saint", desc: "В январе 1938 года власти арестовали священников Ухтомского благочиния Московской епархии, и среди них протоиереев Сергия Лебедева, Сергия Цветкова и Алексия Смирнова и священника Димитрия Гливенко и заключили в Таганскую тюрьму в Москве." },
  { key: "03-22", name: "Николая Горюнова, диакона", kind: "saint", desc: "Священномученик Николай родился в 1880 году в селе Обухово Солнечногорской волости Клинского уезда Московской губернии в семье крестьянина Василия Горюнова." },
  { key: "03-22", name: "прмч. Иоасафа (Шахова), иеромонаха", kind: "saint", desc: "Преподобномученик Иоасаф родился в 1870 году в селе Ильинском Ярославского уезда Ярославской губернии в семье крестьянина Ивана Шахова и в крещении наречен был Николаем [1] ." },
  { key: "03-22", name: "Наталии Ульяновой, послушницы", kind: "saint", desc: "Преподобномученица Наталия родилась в 1889 году в городе Ельце Орловской губернии в семье столяра Николая Николаевича Ульянова. В 1910 году Наталья приехала в Москву, поступила в Новодевичий монастырь и подвизалась в нем на различных послушаниях до его закрытия в 1922 году." },
  { key: "03-22", name: "Александры (Самойловой), инокини", kind: "saint", desc: "Преподобномученица Александра родилась 22 апреля 1882 года в деревне Гриднево Гжатского уезда Смоленской губернии в семье благочестивых крестьян Никиты и Евдокии Самойловых." },
  { key: "03-22", name: "Слово плоть бысть Албазинская", year: "1666", kind: "saint", desc: "Албазинская икона Божией Матери &quot;Слово плоть бысть&quot; — великая святыня Приамурья, свое название получила от русской крепости Албазин (ныне село Албазино) на Амуре, основанной в 1650 году знаменитым русским землепроходцем атаманом Ерофеем Хабаровым на месте городка даурского князя Албазы." },
  { key: "03-23", name: "прав. Павла Таганрогского", kind: "saint", desc: "Прав. Павел Таганрогский (1792–1879), дворянский сын, раздал имущество и посвятил жизнь Богу. Поселившись в Таганроге, он жил в бедности, работал в порту, молился и наставлял людей." },
  { key: "03-23", name: "прп. Анастасии Патрикии", kind: "saint", desc: "Преподобная Анастасия жила в Константинополе и происходила из аристократической семьи. Благочестивая патрицианка была для многих образцом добродетели и пользовалась большим уважением императора Юстиниана (527–565)." },
  { key: "03-23", name: "Сщмч. Димитрия Легейдо, пресвитера", kind: "saint", desc: "Священномученик Димитрий родился 26 октября 1880 года в селе Большие Сорочинцы Полтавской губернии в семье казака Константина Легейдо. Успешно занимаясь торговлей, Константин Легейдо приумножал земное имущество." },
  { key: "03-24", name: "Свт. Софрония, патриарха Иерусалимского", kind: "saint", desc: "Святитель Софроний, патриарх Иерусалимский, родился в Дамаске. С юных лет он отличался благочестием и любовью к наукам. Особенно он преуспел в философии, за что его стали называть Премудрым." },
  { key: "03-24", name: "свт. Евфимия, архиепископа Новгородского, чудотворца", kind: "saint", desc: "Родился в Великом Новгороде в благочестивой христианской семье. Родители святого долго не имели детей и усердно молили Бога и Пресвятую Богородицу о разрешении их неплодства." },
  { key: "03-24", name: "Прп. Софрония, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Софроний, затворник, подвизался в Дальних (Феодосиевых) пещерах Киево-Печерского монастыря в XIII в. Преподобный Софроний, затворивши себя в темной пещере, ежедневно прочитывал всю Псалтырь и всегда носил на себе власяницу и тяжелый пояс железный." },
  { key: "03-24", name: "прп. Алексия Голосеевского, Киевского, иеромонаха", kind: "saint", desc: "Преподобный Алексий Голосеевский родился 14 апреля 1840 года, в первый день Пасхи, в многодетной дворянской семье. Мальчик родился немым. Семье Шепелевых покровительствовал Киевский митрополит Филарет (Амфитеатров) ." },
  { key: "03-24", name: "сщмч. Пиония, пресвитера Смирнского, и иже с ним", kind: "saint", desc: "Священномученики Пионий и Лин, пресвитеры Смирнские, святые мученицы Савина и Македония и святой мученик Асклипиад пострадали во время гонения на христиан в царствование Декия (249–251) в Смирне, знаменитом в древности торговом городе, расположенном на восточном берегу Эгейского моря." },
  { key: "03-24", name: "мч. Епимаха Нового", kind: "saint", desc: "Св. мученик Епимах, египетский отшельник с горы Пелусийской, во время гонений в Александрии (ок. 250 г.) публично разрушил языческих идолов, исповедав христианство." },
  { key: "03-24", name: "свт. Софрония, епископа Врачанского (1813)", kind: "saint", desc: "Святитель Софроний (1739 - 1813), епископ Врачанский, был одним из выдающихся деятелей болгарского возрождения. В миру Стойко Владиславов, родился в городе Котел (Казан), Болгария, в Османской империи, в православном семействе зажиточного торговца скотом." },
  { key: "03-24", name: "Прп. Патрикия (Петрова) исп., иеромонаха", kind: "saint", desc: "Преподобноисповедник Патрикий родился 5 марта 1877 года в деревне Дьяконово Архангельской волости Кологривского уезда Костромской губернии в семье крестьянина Петра Петрова и в крещении был наречен Павлом." },
  { key: "03-24", name: "св. Василия Малахова исп., пресвитера", kind: "saint", desc: "Священноисповедник Василий родился 30 января 1873 года в деревне Дуброво Тиостянской волости Городокского уезда Витебской губернии в семье белорусского крестьянина Иакова Малахова." },
  { key: "03-25", name: "Прп. Феофана исп., Сигрианского", kind: "saint", desc: "Преподобный Феофан Исповедник родился в Константинополе в благочестивой и знатной семье. Отец Феофана был в родстве с византийским императором Львом Исавром (717–741)." },
  { key: "03-25", name: "Прав. Финееса, первосвященника Израильского", kind: "saint", desc: "Святой праведный Финеес, внук первосвященника Аарона и сын первосвященника Елеазара, тоже был священником и ревностно исполнял свое служение. Когда израильтяне, выведенные из Египта святым пророком Моисеем (память 17 сентября), были уже бли" },
  { key: "03-25", name: "свт. Григория Двоеслова, папы Римского", kind: "saint", desc: "Св. Григорий, именуемый Двоесловом (собеседником), родился в Риме ок. 540 г. Принадлежал к древнему патрицианскому роду, в котором были христиане, даже святые." },
  { key: "03-25", name: "прп. Симеона Нового Богослова, игумена", kind: "saint", desc: "Прп. Симеон Новый Богослов (946–1021) родился в Пафлагонии, получил основательное образование и служил при императорском дворе. В 25 лет оставил мир и поступил в Студийский монастырь." },
  { key: "03-25", name: "Св. Александра Державина исп., пресвитера", kind: "saint", desc: "Священноисповедник Александр родился 13 августа 1864 года в селе Зеленцино Клинского уезда Московской губернии в семье священника Сергея Ивановича Державина." },
  { key: "03-25", name: "Иоанна Плеханова", kind: "saint", desc: "Священномученик Иоанн родился 11 сентября 1879 года в деревне Филипково Переславского уезда Владимирской губернии в семье крестьянина Гавриила Плеханова." },
  { key: "03-25", name: "Константина Соколова", kind: "saint", desc: "Священномученик Константин родился 3 мая 1875 года в селе Люберцы Московского уезда Московской губернии в семье диакона Михаила Соколова. В 1896 году Константин окончил Московскую Духовную семинарию и был рукоположен во священника." },
  { key: "03-25", name: "прмч. Владимира (Волкова), архимандрита", kind: "saint", desc: "Преподобномученик Владимир родился 21 апреля 1878 года в деревне Малые Палатки Гжатского уезда Смоленской губернии в семье крестьянина Нила Волкова и в крещении наречен был Георгием." },
  { key: "03-25", name: "сщмч. Сергия Скворцова, пресвитера", kind: "saint", desc: "Священномученик Сергий родился 4 июля 1896 года в деревне Смольниково Клинского уезда Московской губернии в семье печника Иосифа Скворцова и его супруги Екатерины." },
  { key: "03-25", name: "Лиддская (На столпе в Лидде)", kind: "saint", desc: "В городе Лидде (впоследствии Диосполе), недалеко от Иерусалима, где святые апостолы Петр (память 29 июня и 16 января) и Иоанн Богослов (память 8 мая и 26 сентября) проповедовали Господа Иисуса Христа, для новообращенных был сооружен храм во имя Пресвятой Богородицы." },
  { key: "03-26", name: "свт. Никифора, патриарха Константинопольского", kind: "saint", desc: "Свт. Никифор Исповедник (ок. 758-828) ‒ патриарх Константинопольский (806-815), выдающийся борец с иконоборчеством. Родился в благочестивой семье, получил блестящее образование." },
  { key: "03-26", name: "Мч. Савина Ермопольского (Египетского)", kind: "saint", desc: "Святой мученик Савин был правителем египетского города Гермополя. Во время гонений на христиан при императоре Диоклитиане (284–305) святой Савин вместе со своими единомышленниками скрылся в отдаленной деревне." },
  { key: "03-26", name: "мч. Александра Пиднского", kind: "saint", desc: "Святой мученик Александр был пресвитером в городе Пидне, недалеко от Солуни. Своей проповедью святой обратил многих язычников в христианство. Во время гонений на христиан при императоре Максимиане Галерии (305-311) святой Александр был подвергнут жестоким истязаниям, а затем обезглавлен." },
  { key: "03-26", name: "мц. Христины Персидской", kind: "saint", desc: "Святая мученица Христина Персидская за исповедание веры Христовой была до смерти бита бичами в IV веке. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопк" },
  { key: "03-26", name: "прп. Анина Халкидонского, пресвитера", kind: "saint", desc: "Преподобный Анин монах родился в Халкидоне в христианской семье. После смерти родителей он в пятнадцатилетнем возрасте удалился в монастырь, где принял иноческий постриг." },
  { key: "03-26", name: "Сщмч. Николая Попова, пресвитера", kind: "saint", desc: "Священномученик Николай Попов родился 6 мая 1864 года в семье статского советника Черкасской станицы Войска Донского Харитона Ивановича Попова и дочери священника станицы Мигулинской Александры Петровны." },
  { key: "03-26", name: "сщмч. Григория Поспелова, пресвитера", kind: "saint", desc: "Священномученик Григорий родился 12 декабря 1877 года в семье певчего Придворной певческой капеллы в Санкт-Петербурге Иоанна Поспелова, который впоследствии был рукоположен во диакона и закончил свою жизнь диаконом Морской Богоявленской церкви в Кронштадте." },
  { key: "03-27", name: "Прп. Венедикта Нурсийского, игумена", kind: "saint", desc: "Преподобный Венедикт, основатель западного монашеского ордена бенедиктинцев, родился в итальянском городе Нурсии в 480 году. В 14 лет святой был отправлен родителями на ученье в Рим, однако, угнетенный окружавшей его безнравственностью, он решил посвятить себя другой жизни." },
  { key: "03-27", name: "Свт. Феогноста, митрополита Киевского и всея Руси", kind: "saint", desc: "Свт. Феогност, грек по происхождению, возглавлял Киевскую и Владимирскую митрополию в XIV веке, сделав Москву своей резиденцией. Он был верным союзником московских князей." },
  { key: "03-27", name: "блгв. вел. кн. Ростислава (в Крещении Михаила) Мстиславича Киевского", kind: "saint", desc: "Святой Ростислав, великий князь Киевский, сын великого князя Киевского святого Мстислава Великого (&dagger; 1132, память 14 июня), брат святого князя Всеволода-Гавриила (&dagger; 1138, память 11 февраля, 22 апреля и 27 ноября), является одним из выдающихся государственных и церковных деятелей Руси середины XII века." },
  { key: "03-27", name: "свт. Евсхимона исп., епископа Лампсакийского", kind: "saint", desc: "Святой Евсхимон Исповедник, епископ Лампсакийский, живший в Малой Азии на берегу Дарданельского пролива, известен своей добродетельной, подвижнической жизнью." },
  { key: "03-27", name: "Феодоровская", kind: "saint", desc: "Судьба этого чудотворного образа тесно переплетена с судьбами России, ибо Феодоровская была родовой иконой дома Романовых. Сама икона, по преданию написанная апостолом и евангелистом Лукою , была обретена святым благоверным князем Георгием Всеволодовичем в часовне близ волжского Городца." },
  { key: "03-28", name: "Сщмч. Александра, иерея в Сиде", kind: "saint", desc: "Священномученик Александр, иерей в Сиде, пострадал за Христа во время гонения при императоре Аврелиане (270–275). Святой был допрошен правителем Антонином и отдан на жестокие истязания." },
  { key: "03-28", name: "мч. Никандра Египтянина", kind: "saint", desc: "Святой мученик Никандр пострадал в Египте при императоре Диоклитиане (284–305). Он был врачом и во время гонений посещал заключенных в темницах христиан, оказывал им помощь, приносил пищу, а умерших погребал." },
  { key: "03-28", name: "Сщмч. Алексия Виноградова, пресвитера", kind: "saint", desc: "Священномученик Алексий родился 28 декабря 1871 года в городе Москве в семье чиновника Святейшего Синода Петра Виноградова, впоследствии ставшего священником." },
  { key: "03-28", name: "сщмч. Михаила Богословского, пресвитера", kind: "saint", desc: "Священномученик Михаил родился 5 сентября 1883 года в селе Сошки Липецкого уезда Тамбовской губернии в семье псаломщика Константина Богословского. В 1905 году Михаил Константинович окончил Тамбовскую Духовную семинарию, в 1909-м — Санкт-Пет" },
  { key: "03-29", name: "Прп. Марии Египетской", kind: "saint", desc: "Преподобная Мария, прозванная Египетской, жила в середине V и в начале VI столетия. Ее молодость не предвещала ничего хорошего. Марии исполнилось лишь двенадцать лет, когда она ушла из своего дома в городе Александрии." },
  { key: "03-29", name: "Мч. Савина Ермопольского (Египетского)", kind: "saint", desc: "Святой мученик Савин был правителем египетского города Гермополя. Во время гонений на христиан при императоре Диоклитиане (284–305) святой Савин вместе со своими единомышленниками скрылся в отдаленной деревне." },
  { key: "03-29", name: "мч. Папы Ларандского", kind: "saint", desc: "Святой мученик Папа жил в городе Ларанде (Малая Азия) в царствование Максимиана (305–311). Его судили и пытали за веру во Христа, затем в сапогах со вбитыми внутрь острием гвоздями вели для повторного суда в город Диокесарию и далее в Селевкию Исаврийскую." },
  { key: "03-29", name: "Свт. Серапиона, архиепископа Новгородского", kind: "saint", desc: "Родился в подмосковном селе Пехорке и с юных лет стремился к иночеству. По воле родителей вступил в брак, принял сан священства, но через год овдовел и принял пострижение в Дубенском Успенском монастыре." },
  { key: "03-29", name: "ап. от 70-ти Аристовула, епископа Вританийского (Британского)", kind: "saint", desc: "Святой апостол из 70-ти Аристовул, епископ Вританийский (Британский), родился на Кипре. Вместе со своим братом, святым апостолом из 70-ти Варнавой, он сопровождал святого апостола Павла в его путешествиях." },
  { key: "03-29", name: "сщмч. Александра I, папы Римского", kind: "saint", desc: "Священномученик Александр, папа римский, занимал папский престол в течение 10 лет. Он был заживо сожжен 3 мая 119 года по повелению императора Адриана (117–138)." },
  { key: "03-29", name: "мч. Иулиана Аназарвского", kind: "saint", desc: "Священномученик Иулиан Аназаврский пострадал за Христа в Антиохии Сирийской при императоре Максимиане Галерии (305–311). Мощи его при святителе Иоанне Златоусте (&dagger; 407) прославились чудесами." },
  { key: "03-30", name: "Прп. Алексия, человека Божия", kind: "saint", desc: "Преподобный Алексий, человек Божий, родился в Риме от знатных и благочестивых родителей. Отец его Евфимиан был сенатором. Он отличался душевной добротой, был милосерден к больным и страждущим, ежедневно устраивал у себя дома три стола: для сирот и вдов, для путников и для нищих." },
  { key: "03-30", name: "прп. Макария, игумена Калязинского, чудотворца", kind: "saint", desc: "В миру Матфей Кожин — сын боярина. Овдовев, принял постриг. Около 1434 г. ушёл в пустынное место близ Калязина, где основал обитель во имя Святой Троицы (будущий Калязинский Макариев монастырь), став в ней первым игуменом." },
  { key: "03-30", name: "Прп. Парфения Киевского, иеросхимонаха", kind: "saint", desc: "Преподобный Парфений (Краснопевцев) Киевский [*] (1790–1855), иеросхимонах, духовник Киево-Печерской Лавры . В миру Краснопевцев Пётр Иванович, родился в селе Симонове Алексинского уезда Тульской губернии 24 августа 1790 года в семье церковного причетника." },
  { key: "03-30", name: "мч. Марина Кесарийского", kind: "saint", desc: "Мч. Марин пострадал за Христа, разрушив языческий жертвенник и поправ жертвенные дары. После жестоких пыток был обезглавлен. Святой Марин, вдохновленный пламенной любовью ко Христу Спасителю, на одном из праздников в идольском капище разрушил жертвенник, стал топтать ногами жертвы и при всех исповедал себя христианином." },
  { key: "03-30", name: "свт. Патрикия, просветителя Ирландии, епископа", kind: "saint", desc: "Апостол Крайнего Запада святой Патрикий [*] (Патрик) родился в Британии около 383 года в галло-римской семье, которая уже давно приняла христианство. Его отец Кальпурний был диаконом и в то же время исполнял обязанности декуриона." },
  { key: "03-30", name: "Сщмч. Александра Поливанова, пресвитера", kind: "saint", desc: "Священномученик Александр служил священником в Троицком храме в селе Алтата Ачинского уезда Енисейской губернии. Он был расстрелян большевиками в четырех верстах от села Алтата 30 марта 1919 года." },
  { key: "03-30", name: "сщмч. Виктора Киранова, пресвитера", kind: "saint", desc: "Священномученик Виктор родился 8 марта 1881 года в селе Мануиловка Бердянского уезда Таврической губернии в семье священника Михаила Киранова; его предки были болгарами, спасаясь от турок, они приехали в Россию в 1830 году." },
  { key: "03-31", name: "Свт. Кирилла, архиепископа Иерусалимского", kind: "saint", desc: "Святой Кирилл, архиепископ Иерусалимский, родился в Иерусалиме в 315 году и был воспитан в строгом христианском благочестии. Достигнув совершеннолетия, он принял монашество, а в 346 году стал пресвитером." },
  { key: "03-31", name: "прп. Анина Халкидонского, монаха", kind: "saint", desc: "Преподобный Анин монах родился в Халкидоне в христианской семье. После смерти родителей он в пятнадцатилетнем возрасте удалился в монастырь, где принял иноческий постриг." },
  { key: "03-31", name: "Сщмч. Димитрия Розанова, пресвитера", kind: "saint", desc: "Священномученик Димитрий родился 10 октября 1889 года в селе Бардино Коломенского уезда Московской губернии в семье псаломщика Павла Розанова. По окончании в 1907 году Коломенского духовного училища он женился на Елизавете Павловне Кедровой" },
  { key: "03-31", name: "прмц. Наталии (Баклановой), инокини", kind: "saint", desc: "Преподобномученица Наталия родилась в 1890 году в селе Шестово Подольского уезда Московской губернии в семье крестьянина Василия Бакланова. Когда девочке исполнилось восемь лет, родители отдали ее в школу, по окончании которой она сначала п" },
];
